WITH filtered AS (SELECT id, city, region, sqft, LENGTH(store_name) AS store_name_length, REPLACE(store_name, ' ', '_') AS store_name_slug FROM stores WHERE region IS NOT NULL) SELECT CASE WHEN store_name_length >= 68 THEN 'PREMIUM' ELSE 'STANDARD' END AS store_name_length_tier, CASE WHEN sqft >= 14907 THEN 'HIGH' ELSE 'LOW' END AS sqft_tier, BIT_OR(sqft) AS sqft_bit_or, BIT_OR(sqft) AS sqft_bit_or_2, SIZE(COLLECT_SET(city)) AS num_cities, SORT_ARRAY(COLLECT_SET(city)) AS city_list, COUNT(DISTINCT city) AS distinct_cities, AVG(store_name_length) AS avg_store_name_length, GROUPING_ID() AS grouping_id FROM filtered GROUP BY GROUPING SETS ((CASE WHEN store_name_length >= 68 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN sqft >= 14907 THEN 'HIGH' ELSE 'LOW' END), (CASE WHEN store_name_length >= 68 THEN 'PREMIUM' ELSE 'STANDARD' END)) HAVING BIT_OR(sqft) >= 1;
